import { describe, it, expect } from 'vitest';
import { appendChangeLog } from '../repo';
import { supabase } from '@/utils/supabase';

describe('appendChangeLog', () => {
  beforeEach(() => {
    supabase.from.mockReset();
  });

  it('should insert changelog entry without explicit id', async () => {
    const data = {
      user_id: 'user123',
      action: 'updated',
      table: 'library',
      record_id: 'lib456',
      description: 'Updated library entry'
    };
    await appendChangeLog(data);

    const [insertCall] = supabase.from.mock.calls[0];
    expect(insertCall[0]).toEqual({
      user_id: 'user123',
      action: 'updated',
      table: 'library',
      record_id: 'lib456',
      description: 'Updated library entry'
    });
  });

  it('should propagate insert errors', async () => {
    const data = {
      user_id: 'user123',
      action: 'updated',
      table: 'library',
      record_id: 'lib456',
      description: 'Updated library entry'
    };
    supabase.from.mockImplementationOnce(() => ({
      data: null,
      error: new Error('Database error')
    }));

    await expect(appendChangeLog(data)).rejects.toThrow('Database error');
  });
});

